<div x-data="supplierAutocomplete()" x-init="init()" {{ $attributes->class(['chm-supplier-picker']) }} @keydown.escape="open=false">
    <div class="chm-supplier-picker__name-field">@if($showLabel ?? false)<span class="chm-supplier-picker__field-label">{{ $label ?? 'Fornecedor' }}</span>@endif<input x-ref="name" class="chm-supplier-picker__input" name="{{ $textName ?? 'supplier_name' }}" value="{{ $initialText ?? $value ?? '' }}" maxlength="255" placeholder="{{ $placeholder ?? 'Nome do fornecedor' }}" autocomplete="off" @if(isset($textModel)) x-model="{{ $textModel }}" @endif @input.debounce.300ms="changed()" @focus="onFocus()" aria-label="{{ $label ?? 'Fornecedor' }}" :aria-invalid="documentError ? 'true' : 'false'"></div>
    <input x-ref="id" type="hidden" name="{{ $idName ?? 'supplier_id' }}" value="{{ $supplierIdValue ?? '' }}" @if(isset($idModel)) x-model="{{ $idModel }}" @endif>
    @if(isset($documentName))
        <div class="chm-supplier-picker__document-field">
            <span>CPF/CNPJ</span>
            <input x-ref="document" class="chm-supplier-picker__input" type="text" name="{{ $documentName }}" value="{{ $initialDocument ?? $documentValue ?? '' }}" maxlength="20" placeholder="{{ $documentPlaceholder ?? 'Opcional' }}" @if(isset($documentModel)) x-model="{{ $documentModel }}" @endif @input="documentChanged()" @blur="validateDocument(true)" aria-label="CPF ou CNPJ do fornecedor" :aria-invalid="documentError ? 'true' : 'false'">
