    <small x-show="!selected && $refs.name.value.trim().length >= 2" class="chm-supplier-picker__manual"><strong>+ Novo fornecedor</strong><span x-text="$refs.document?.value ? 'Será cadastrado automaticamente ao confirmar este lançamento.' : 'Sem CPF/CNPJ — será cadastrado automaticamente ao confirmar este lançamento.'"></span></small>
</div>
@once
<style>.chm-supplier-picker{position:relative;display:grid;gap:7px}.chm-supplier-picker__name-field,.chm-supplier-picker__document-field{display:grid;gap:4px}.chm-supplier-picker__field-label,.chm-supplier-picker__document-field>span{font-size:.72rem;font-weight:700;color:var(--chm-theme-muted,#aebed3)}.chm-supplier-picker__input{width:100%;min-height:40px;padding:9px 11px;border:1px solid var(--chm-theme-border,rgba(148,163,184,.28));border-radius:9px;background:var(--chm-theme-input,#172235);color:var(--chm-theme-text,#e7eef8);font:inherit;box-sizing:border-box}.chm-supplier-picker__input::placeholder{color:var(--chm-theme-muted,#91a0b8)}.chm-supplier-picker__input:focus{outline:0;border-color:var(--chm-theme-primary,#4f9cff);box-shadow:0 0 0 3px color-mix(in srgb,var(--chm-theme-primary,#4f9cff) 18%,transparent)}.chm-supplier-picker--split{grid-template-columns:minmax(0,1fr) minmax(0,1fr);column-gap:12px}.chm-supplier-picker--split .chm-supplier-picker__loading,.chm-supplier-picker--split .chm-supplier-picker__selected,.chm-supplier-picker--split .chm-supplier-picker__results,.chm-supplier-picker--split .chm-supplier-picker__manual{grid-column:1/-1}.chm-supplier-picker__results{position:absolute;z-index:1100;left:0;right:0;top:68px;max-height:240px;overflow:auto;border:1px solid var(--chm-theme-border,#50647f);border-radius:10px;background:var(--chm-theme-card-elevated,#202d42);box-shadow:0 10px 28px rgba(8,17,30,.4)}.chm-supplier-picker__results button{display:grid;width:100%;gap:2px;padding:10px;border:0;border-bottom:1px solid var(--chm-theme-border,#3a4b63);text-align:left;color:var(--chm-theme-text,#e7eef8);background:transparent;cursor:pointer}.chm-supplier-picker__results button:hover{background:var(--chm-theme-input,#2c405e)}.chm-supplier-picker small{display:block;color:var(--chm-theme-muted,#aebed3)}.chm-supplier-picker em{font-size:11px;color:#c58b2c;font-style:normal}.chm-supplier-picker__selected{margin-top:1px;padding:7px 9px;border:1px solid color-mix(in srgb,#36a269 55%,var(--chm-theme-border));border-radius:8px;background:color-mix(in srgb,#36a269 14%,var(--chm-theme-card));color:var(--chm-theme-text,#d5f0df)}.chm-supplier-picker__selected button{float:right;border:0;background:none;color:#d95763;font-size:18px;cursor:pointer}.chm-supplier-picker__loading,.chm-supplier-picker__manual,.chm-supplier-picker__error{font-size:11px}.chm-supplier-picker__manual{display:grid;gap:2px}.chm-supplier-picker__error{color:#d95763}@media(max-width:700px){.chm-supplier-picker--split{grid-template-columns:1fr}.chm-supplier-picker--split .chm-supplier-picker__document-field{grid-column:auto}}</style>
<script>function supplierAutocomplete(){return{open:false,loading:false,results:[],selected:null,controller:null,requestId:0,suppressSearch:false,documentError:'',init(){if(this.$refs.id.value&&this.$refs.name.value)this.selected={id:this.$refs.id.value,name:this.$refs.name.value,formatted_document:this.$refs.document?.value||null};this.$el.closest('form')?.addEventListener('submit',event=>{if(!this.validateDocument(true)){event.preventDefault();this.$refs.document?.focus()}})},setValue(ref,value){if(!this.$refs[ref])return;this.$refs[ref].value=value??'';this.$refs[ref].dispatchEvent(new Event('input',{bubbles:true}))},digits(){return(this.$refs.document?.value||'').replace(/\D/g,'').slice(0,14)},formatDocument(){if(!this.$refs.document)return;let d=this.digits();this.$refs.document.value=d.length<=11?d.replace(/(\d{3})(\d)/,'$1.$2').replace(/(\d{3})(\d)/,'$1.$2').replace(/(\d{3})(\d{1,2})$/,'$1-$2'):d.replace(/^(\d{2})(\d)/,'$1.$2').replace(/^(\d{2})\.(\d{3})(\d)/,'$1.$2.$3').replace(/\.(\d{3})(\d)/,'.$1/$2').replace(/(\d{4})(\d)/,'$1-$2')},validCpf(v){if(!/^\d{11}$/.test(v)||/^(\d)\1+$/.test(v))return false;for(let p=9;p<11;p++){let s=0;for(let i=0;i<p;i++)s+=+v[i]*(p+1-i);if(((s*10)%11)%10!==+v[p])return false}return true},validCnpj(v){if(!/^\d{14}$/.test(v)||/^(\d)\1+$/.test(v))return false;for(const p of[12,13]){let s=0,w=p===12?5:6;for(let i=0;i<p;i++){s+=+v[i]*w;if(--w<2)w=9}if((s%11<2?0:11-s%11)!==+v[p])return false}return true},validateDocument(strict=false){const d=this.digits();if(!d)return this.documentError='',true;if(d.length===11||d.length===14){const ok=d.length===11?this.validCpf(d):this.validCnpj(d);this.documentError=ok?'':'Informe um CPF ou CNPJ válido.';return ok}this.documentError=strict?'Informe um CPF ou CNPJ válido.':'';return !strict},cancelRequest(){this.requestId++;this.controller?.abort();this.controller=null;this.loading=false},clearSelection(){this.selected=null;this.setValue('id','')},onFocus(){if(!this.selected)this.changed()},search(q){this.cancelRequest();const requestId=++this.requestId;this.controller=new AbortController();this.loading=true;fetch(`{{ route('suppliers.search') }}?q=${encodeURIComponent(q)}`,{headers:{Accept:'application/json'},signal:this.controller.signal}).then(r=>r.json()).then(items=>{if(requestId!==this.requestId||this.selected)return;this.results=items;this.open=true}).catch(e=>{if(e.name!=='AbortError'&&requestId===this.requestId){this.results=[];this.open=false}}).finally(()=>{if(requestId===this.requestId)this.loading=false})},changed(){if(this.suppressSearch)return;const q=this.$refs.name.value.trim();if(this.selected){if(q===this.selected.name)return;this.clearSelection()}if(q.length<2){this.cancelRequest();this.open=false;this.results=[];return}this.search(q)},documentChanged(){if(this.suppressSearch)return;this.formatDocument();this.validateDocument(false);if(this.selected)this.clearSelection();const d=this.digits();if((d.length===11||d.length===14)&&this.validateDocument())this.search(d)},select(item){this.suppressSearch=true;this.cancelRequest();this.selected=item;this.results=[];this.open=false;this.documentError='';this.setValue('id',item.id);this.setValue('name',item.name);this.setValue('document',item.formatted_document??item.document??'');this.$nextTick(()=>{this.suppressSearch=false})},clear(){this.cancelRequest();this.results=[];this.open=false;this.selected=null;this.setValue('id','');this.setValue('document','');this.$refs.name.focus();this.$nextTick(()=>this.changed())}}}</script>
@endonce
